import { useState, useEffect, useCallback } from "react";

// ── CONSTANTS & API ────────────────────────────────────────────────────────
const SUPABASE_URL = "https://odhxxcjkaqfnnnfiyqac.supabase.co";
const SUPABASE_ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im9kaHh4Y2prYXFmbm5uZml5cWFjIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzI0NzgxOTUsImV4cCI6MjA4ODA1NDE5NX0.JnKTzwbUKc70EtS_q3ZkVuSSeMa-QppS8HGI-w7YJx4";

const api = async (path, opts = {}) => {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    headers: { apikey: SUPABASE_ANON, Authorization: `Bearer ${SUPABASE_ANON}`, "Content-Type": "application/json", Prefer: opts.prefer || "return=representation", ...opts.headers },
    ...opts,
  });
  if (!res.ok) throw new Error(await res.text());
  const text = await res.text();
  return text ? JSON.parse(text) : null;
};

const db = {
  get: (t, q = "") => api(`${t}?${q}`),
  post: (t, b) => api(t, { method: "POST", body: JSON.stringify(b) }),
  patch: (t, q, b) => api(`${t}?${q}`, { method: "PATCH", body: JSON.stringify(b) }),
  del: (t, q) => api(`${t}?${q}`, { method: "DELETE", prefer: "return=minimal" }),
};

const RUBRICS = [
  { id: 1,  activity: "Attend Non-Mandatory Course (Half Day)", points: 10, icon: "📚" },
  { id: 2,  activity: "Attend Non-Mandatory Course (Full Day)", points: 20, icon: "📚" },
  { id: 3,  activity: "Complete Online e-Learning Module",       points: 5,  icon: "💻" },
  { id: 4,  activity: "Lead a Knowledge Sharing Session",         points: 25, icon: "🎤" },
  { id: 5,  activity: "Participate in Community Service",         points: 15, icon: "🤝" },
  { id: 6,  activity: "Complete a Fitness Challenge",             points: 10, icon: "🏃" },
  { id: 7,  activity: "Mentor a Junior Officer",                  points: 20, icon: "🌱" },
  { id: 8,  activity: "Submit Innovation Idea",                   points: 15, icon: "💡" },
  { id: 9,  activity: "Achieve a Professional Certification",     points: 50, icon: "🏅" },
  { id: 10, activity: "Volunteer for Extra Assignment",           points: 10, icon: "⭐" },
];

const CATALOGUE = [
  { id: "v1", cat: "Vouchers",    name: "NTUC FairPrice $10",   desc: "$10 grocery voucher",      cost: 40,  icon: "🛒", color: "#22c55e", tba: false },
  { id: "v2", cat: "Vouchers",    name: "Grab $10",             desc: "$10 ride / food credits",  cost: 40,  icon: "🚗", color: "#f59e0b", tba: false },
  { id: "v3", cat: "Vouchers",    name: "NTUC FairPrice $25",   desc: "$25 grocery voucher",      cost: 90,  icon: "🛒", color: "#22c55e", tba: false },
  { id: "v4", cat: "Vouchers",    name: "Grab $25",             desc: "$25 ride / food credits",  cost: 90,  icon: "🚗", color: "#f59e0b", tba: false },
  { id: "v5", cat: "Vouchers",    name: "Shopping Voucher $50", desc: "Capitaland / Lazada",       cost: 180, icon: "🛍️", color: "#a855f7", tba: false },
  { id: "l1", cat: "Leave",       name: "Half-Day Off-in-Lieu", desc: "Take half a day off",       cost: 60,  icon: "🌅", color: "#06b6d4", tba: false },
  { id: "l2", cat: "Leave",       name: "Full-Day Off-in-Lieu", desc: "Take a full day off",       cost: 110, icon: "🏖️", color: "#06b6d4", tba: false },
  { id: "p1", cat: "Coming Soon", name: "Mystery Prize A",      desc: "To be announced",           cost: 50,  icon: "🎁", color: "#ec4899", tba: true },
  { id: "p2", cat: "Coming Soon", name: "Mystery Prize B",      desc: "To be announced",           cost: 120, icon: "🎁", color: "#ec4899", tba: true },
  { id: "p3", cat: "Coming Soon", name: "Mystery Prize C",      desc: "To be announced",           cost: 200, icon: "🎁", color: "#ec4899", tba: true },
];

const TIERS = [
  { name: "Player 1",    min: 0,   max: 99,       icon: "🎮", color: "#8b5cf6" },
  { name: "High Scorer", min: 100, max: 199,      icon: "📈", color: "#f59e0b" },
  { name: "Top Ranker",  min: 200, max: 299,      icon: "💎", color: "#10b981" },
  { name: "All-Star",    min: 300, max: Infinity, icon: "🌟", color: "#000000" },
];

// ── UTILS & THEMES ────────────────────────────────────────────────────────
const CAMPAIGN_END = new Date("2026-12-31");
const getCountdown = () => {
  const d = CAMPAIGN_END - new Date();
  if (d <= 0) return { days: 0, hours: 0, mins: 0, secs: 0 };
  return {
    days:  Math.floor(d / 86400000),
    hours: Math.floor((d % 86400000) / 3600000),
    mins:  Math.floor((d % 3600000) / 60000),
    secs:  Math.floor((d % 60000) / 1000),
  };
};

const initials = name => name.split(" ").map(n => n[0]).join("").slice(0, 2).toUpperCase();

const DARK = {
  bg: "#000000", surface: "rgba(25, 25, 25, 0.8)", surfaceHover: "rgba(255, 255, 255, 0.05)",
  border: "rgba(255, 255, 255, 0.1)", borderA: "rgba(255,255,255,0.2)", text: "#f0f0f0",
  sub: "rgba(255, 255, 255, 0.6)", muted: "rgba(255, 255, 255, 0.4)", nav: "rgba(10,10,10,0.8)",
  inputBg: "rgba(255,255,255,0.05)", inputBdr: "rgba(255,255,255,0.1)", div: "rgba(255,255,255,0.08)",
  blank: "rgba(255,255,255,0.03)", infoBg: "rgba(255,255,255,0.02)", shadow: "rgba(0,0,0,0.5)", goldText: "#d4a017",
};

const LITE = {
  bg: "#f8f8f8", surface: "#ffffff", surfaceHover: "#fafafa",
  border: "rgba(0,0,0,0.08)", borderA: "rgba(0,0,0,0.15)", text: "#111111",
  sub: "rgba(0,0,0,0.5)", muted: "rgba(0, 0, 0, 0.35)", nav: "rgba(255,255,255,0.9)",
  inputBg: "#ffffff", inputBdr: "rgba(0,0,0,0.1)", div: "rgba(0,0,0,0.05)",
  blank: "#eee", infoBg: "rgba(0,0,0,0.02)", shadow: "rgba(0,0,0,0.05)", goldText: "#a07000",
};

export default function App() {
  const [dark, setDark] = useState(true);
  const c = dark ? DARK : LITE;

  // Data States
  const [branches, setBranches] = useState([]);
  const [officers, setOfficers] = useState([]);
  const [subs, setSubs]         = useState([]);
  const [redems, setRedems]     = useState([]);
  const [loading, setLoading]   = useState(true);
  const [dbErr, setDbErr]       = useState(null);
  const [adminPwd, setAdminPwd] = useState("admin1234");

  // UI States
  const [screen, setScreen]     = useState("landing");
  const [user, setUser]         = useState(null);
  const [isAdmin, setIsAdmin]   = useState(false);
  const [tab, setTab]           = useState("leaderboard");
  const [leaderboardTab, setLeaderboardTab] = useState("officers");
  const [cd, setCd]             = useState(getCountdown());
  const [toast, setToast]       = useState(null);
  const [confirm, setConfirm]   = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [catF, setCatF]         = useState("All");

  // Form States
  const [selBranch, setSelBranch] = useState("");
  const [selName, setSelName]     = useState("");
  const [adminBox, setAdminBox]   = useState(false);
  const [adminIn, setAdminIn]     = useState("");
  const [form, setForm]           = useState({ rubricId: "", date: "", desc: "" });

  // Admin Management States
  const [newName, setNewName]     = useState("");
  const [newBr, setNewBr]         = useState("");
  const [newBrName, setNewBrName] = useState("");
  const [newPw, setNewPw]         = useState("");
  const [sLoading, setSLoading]   = useState(false);
  const [editOf, setEditOf]       = useState(null);
  const [editN, setEditN]         = useState("");
  const [editB, setEditB]         = useState("");

  const load = useCallback(async () => {
    try {
      setDbErr(null);
      const [br, of, su, re, cfg] = await Promise.all([
        db.get("branches", "order=name.asc"),
        db.get("officers", "order=total_points.desc&select=*,branches(name)"),
        db.get("submissions", "order=created_at.desc"),
        db.get("redemptions", "order=created_at.desc"),
        db.get("config", "key=eq.admin_password"),
      ]);
      setBranches(br || []);
      setOfficers((of || []).map(o => ({ ...o, unit: o.branches?.name || "" })));
      setSubs(su || []);
      setRedems(re || []);
      if (cfg?.[0]) setAdminPwd(cfg[0].value);
    } catch (e) { setDbErr(e.message); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);
  useEffect(() => { const id = setInterval(() => setCd(getCountdown()), 1000); return () => clearInterval(id); }, []);

  const msg = (text, type = "ok") => { setToast({ text, type }); setTimeout(() => setToast(null), 3200); };

  // Computed Values
  const sorted     = [...officers].sort((a, b) => b.total_points - a.total_points);
  const unitScores = branches.map(br => {
    const ofs = officers.filter(o => o.unit === br.name);
    const total = ofs.reduce((s, o) => s + o.total_points, 0);
    return { unit: br.name, total, count: ofs.length, avg: ofs.length ? Math.round(total / ofs.length) : 0 };
  }).sort((a, b) => b.avg - a.avg);
  const byBranch  = branches.reduce((a, br) => { a[br.name] = officers.filter(o => o.unit === br.name); return a; }, {});

  const myOf      = user ? officers.find(o => o.id === user.id) : null;
  const mySpent   = user ? redems.filter(r => r.officer_id === user.id && r.status !== "rejected").reduce((s, r) => s + r.cost, 0) : 0;
  const myAvail   = myOf ? myOf.total_points - mySpent : 0;
  const myRank    = user ? sorted.findIndex(o => o.id === user.id) + 1 : null;
  const mySubs    = user ? subs.filter(s => s.officer_id === user.id) : [];

  const cats      = ["All", ...Array.from(new Set(CATALOGUE.map(p => p.cat)))];
  const catItems  = catF === "All" ? CATALOGUE : CATALOGUE.filter(p => p.cat === catF);

  const tierPts   = myOf?.total_points || 0;
  const tierIdx   = Math.max(0, TIERS.findIndex(t => tierPts >= t.min && tierPts <= t.max));
  const tier      = TIERS[tierIdx];
  const nextTier  = TIERS[tierIdx + 1] || null;
  const tierBarPct = nextTier ? Math.min(100, Math.round(((tierPts - tier.min) / (nextTier.min - tier.min)) * 100)) : 100;
  const tierPtsLeft = nextTier ? nextTier.min - tierPts : 0;

  // Actions
  const enterOfficer = () => {
    const o = officers.find(o => o.name === selName && o.unit === selBranch);
    if (!o) return;
    setUser(o); setIsAdmin(false); setTab("leaderboard"); setScreen("portal");
  };

  const enterAdmin = () => {
    if (adminIn === adminPwd) { setIsAdmin(true); setUser(null); setTab("approvals"); setScreen("portal"); }
    else msg("Incorrect Password", "err");
  };

  const submitAct = async () => {
    if (!form.rubricId || !form.date || !form.desc.trim()) return;
    const r = RUBRICS.find(rub => rub.id === parseInt(form.rubricId));
    try {
      await db.post("submissions", { officer_id: user.id, officer_name: user.name, unit: user.unit, activity: r.activity, icon: r.icon, points: r.points, date: form.date, description: form.desc, status: "pending" });
      setForm({ rubricId: "", date: "", desc: "" });
      msg("Submitted! Awaiting approval 🎯"); await load(); setTab("mylog");
    } catch (e) { msg(e.message, "err"); }
  };

  const approve = async (s) => {
    try {
      await db.patch("submissions", `id=eq.${s.id}`, { status: "approved" });
      await db.patch("officers", `id=eq.${s.officer_id}`, { total_points: (officers.find(o => o.id === s.officer_id)?.total_points || 0) + s.points });
      msg("Approved!"); await load();
    } catch (e) { msg(e.message, "err"); }
  };

  const redeemP = async (p) => {
    try {
      await db.post("redemptions", { officer_id: user.id, officer_name: user.name, unit: user.unit, prize_name: p.name, prize_icon: p.icon, cost: p.cost, status: "pending" });
      setConfirm(null); msg("🎁 Redemption requested!"); await load();
    } catch (e) { msg(e.message, "err"); }
  };

  // Styles
  const card = { background: c.surface, border: `1px solid ${c.border}`, borderRadius: 12, boxShadow: `0 4px 12px ${c.shadow}` };
  const inp  = { width: "100%", padding: "12px", background: c.inputBg, border: `1px solid ${c.inputBdr}`, borderRadius: 8, color: c.text, fontSize: 15, outline: "none" };

  if (loading) return <div style={{ minHeight: "100vh", background: c.bg, display: "flex", alignItems: "center", justifyContent: "center", color: c.muted }}>Loading...</div>;

  // ── RENDER: LANDING ──────────────────────────────────────────────────────
  if (screen === "landing") return (
    <div style={{ minHeight: "100vh", background: c.bg, color: c.text, fontFamily: "Inter, sans-serif" }}>
      <CSS c={c} dark={dark} />
      <div style={{ background: dark ? "#111" : "#eee", padding: "8px 0", textAlign: "center", fontSize: 13, fontWeight: 700 }}>
         ⏱️ GEAR UP 2026 ENDS IN: {cd.days}D {cd.hours}H {cd.mins}M {cd.secs}S
      </div>
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "60px 24px" }} className="landing-grid">
        <div className="up">
          <h1 style={{ fontSize: 48, fontWeight: 900, marginBottom: 16 }}>🚀 GEAR Up</h1>
          <p style={{ fontSize: 18, color: c.sub, marginBottom: 40 }}>Driving officer-led development at TRACOM.</p>
          <div style={{ ...card, padding: 32 }}>
            {!adminBox ? (
              <>
                <label style={{ fontSize: 12, color: c.muted, display: "block", marginBottom: 8 }}>BRANCH</label>
                <select value={selBranch} onChange={e => { setSelBranch(e.target.value); setSelName(""); }} style={{ ...inp, marginBottom: 20 }}>
                  <option value="">Select branch...</option>
                  {branches.map(b => <option key={b.id} value={b.name}>{b.name}</option>)}
                </select>
                {selBranch && (
                  <>
                    <label style={{ fontSize: 12, color: c.muted, display: "block", marginBottom: 8 }}>YOUR NAME</label>
                    <select value={selName} onChange={e => setSelName(e.target.value)} style={{ ...inp, marginBottom: 24 }}>
                      <option value="">Select name...</option>
                      {(byBranch[selBranch] || []).map(o => <option key={o.id} value={o.name}>{o.name}</option>)}
                    </select>
                  </>
                )}
                <button onClick={enterOfficer} disabled={!selName} style={{ width: "100%", padding: 14, borderRadius: 8, background: selName ? c.text : c.blank, color: dark ? "#000" : "#fff", border: "none", fontWeight: 700, cursor: "pointer" }}>Enter Portal →</button>
                <button onClick={() => setAdminBox(true)} style={{ width: "100%", marginTop: 16, background: "none", border: "none", color: c.muted, fontSize: 13, cursor: "pointer" }}>Admin Login</button>
              </>
            ) : (
              <div style={{ textAlign: "center" }}>
                <input type="password" placeholder="Admin Password" value={adminIn} onChange={e => setAdminIn(e.target.value)} style={{ ...inp, marginBottom: 16 }} />
                <button onClick={enterAdmin} style={{ width: "100%", padding: 14, borderRadius: 8, background: c.text, color: dark ? "#000" : "#fff", border: "none", fontWeight: 700 }}>Admin Login</button>
                <button onClick={() => setAdminBox(false)} style={{ marginTop: 16, background: "none", border: "none", color: c.sub, cursor: "pointer" }}>Back</button>
              </div>
            )}
          </div>
        </div>
        <div className="up" style={{ animationDelay: "0.1s" }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
            <h2 style={{ fontSize: 20, fontWeight: 800 }}>🏆 Top Officers</h2>
            <button onClick={() => setScreen("rubrics")} style={{ background: "none", border: "none", color: c.goldText, fontWeight: 700, cursor: "pointer" }}>How to earn points →</button>
          </div>
          <div style={{ ...card, overflow: "hidden" }}>
            {sorted.slice(0, 5).map((o, i) => (
              <div key={o.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 20px", borderBottom: i < 4 ? `1px solid ${c.border}` : "none" }}>
                <span style={{ fontSize: 20, width: 30 }}>{["🥇","🥈","🥉"][i] || `#${i+1}`}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 700 }}>{o.name}</div>
                  <div style={{ fontSize: 12, color: c.muted }}>{o.unit}</div>
                </div>
                <div style={{ fontWeight: 900, fontSize: 18 }}>{o.total_points} <span style={{ fontSize: 10, color: c.muted }}>PTS</span></div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  // ── RENDER: ABOUT & RUBRICS ──────────────────────────────────────────────
  if (screen === "about" || screen === "rubrics") return (
     <div style={{ minHeight: "100vh", background: c.bg, color: c.text, fontFamily: "Inter, sans-serif" }}>
       <CSS c={c} dark={dark} />
       <div style={{ maxWidth: 800, margin: "0 auto", padding: "40px 20px" }}>
         <button onClick={() => setScreen("landing")} style={{ background: "none", border: "none", color: c.sub, cursor: "pointer", marginBottom: 20 }}>← Back</button>
         {screen === "about" ? <Manifesto c={c} card={card} /> : <PointsGuide c={c} card={card} />}
       </div>
     </div>
  );

  // ── RENDER: PORTAL ───────────────────────────────────────────────────────
  const TABS = isAdmin 
    ? [{ id: "leaderboard", label: "Leaderboard" }, { id: "approvals", label: `Approvals (${subs.filter(s=>s.status==="pending").length})` }, { id: "redemptions", label: `Redems (${redems.filter(r=>r.status==="pending").length})` }, { id: "settings", label: "Settings" }]
    : [{ id: "submit", label: "Log Activity" }, { id: "leaderboard", label: "Leaderboard" }, { id: "mylog", label: "My Log" }, { id: "rewards", label: "Tiers & Prizes" }];

  return (
    <div style={{ minHeight: "100vh", background: c.bg, color: c.text, fontFamily: "Inter, sans-serif" }}>
      <CSS c={c} dark={dark} />

      {/* Toast */}
      {toast && <div className="toast" style={{ background: toast.type === "err" ? "#e11d48" : "#10b981" }}>{toast.text}</div>}

      {/* Confirmation Modal */}
      {confirm && (
        <div className="modal-overlay">
          <div style={{ ...card, padding: 32, maxWidth: 320, textAlign: "center" }} className="up">
            <div style={{ fontSize: 48, marginBottom: 12 }}>{confirm.icon}</div>
            <h3 style={{ marginBottom: 8 }}>{confirm.name}</h3>
            <p style={{ color: c.sub, fontSize: 14, marginBottom: 24 }}>Costs {confirm.cost} pts. Confirm redemption?</p>
            <div style={{ display: "flex", gap: 12 }}>
              <button onClick={() => redeemP(confirm)} style={{ flex: 1, padding: 12, borderRadius: 8, border: "none", background: c.text, color: dark ? "#000" : "#fff", fontWeight: 700 }}>Confirm</button>
              <button onClick={() => setConfirm(null)} style={{ flex: 1, padding: 12, borderRadius: 8, border: `1px solid ${c.border}`, background: "none", color: c.sub }}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Top Bar */}
      <div style={{ borderBottom: `1px solid ${c.div}`, background: c.nav, backdropFilter: "blur(12px)", position: "sticky", top: 0, zIndex: 100 }}>
        <div style={{ maxWidth: 1060, margin: "0 auto", padding: "0 20px", display: "flex", alignItems: "center", height: 60, justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button onClick={() => setMenuOpen(!menuOpen)} className="hamburger">☰</button>
            <span style={{ fontWeight: 900, fontSize: 18 }}>🚀 GEAR Up</span>
          </div>
          <div style={{ display: "flex", gap: 12 }}>
             <button onClick={() => setDark(!dark)} style={{ background: "none", border: "none", fontSize: 20 }}>{dark ? "☀️" : "🌙"}</button>
             <button onClick={() => setScreen("landing")} style={{ background: "none", border: "none", color: "#f87171", fontWeight: 700 }}>Logout</button>
          </div>
        </div>
        {menuOpen && (
          <div style={{ background: c.surface, borderBottom: `1px solid ${c.border}`, padding: 12 }}>
            {TABS.map(t => (
              <button key={t.id} onClick={() => { setTab(t.id); setMenuOpen(false); }} style={{ display: "block", width: "100%", textAlign: "left", padding: 12, background: tab === t.id ? c.blank : "none", border: "none", color: tab === t.id ? c.text : c.sub, borderRadius: 8 }}>{t.label}</button>
            ))}
          </div>
        )}
      </div>

      <div style={{ maxWidth: 1060, margin: "0 auto", padding: "40px 20px" }}>

        {/* TAB: SUBMIT */}
        {tab === "submit" && (
          <div className="up" style={{ maxWidth: 540, margin: "0 auto" }}>
            <div style={{ ...card, padding: 24, marginBottom: 24, background: "linear-gradient(135deg, #6366f1 0%, #a855f7 100%)", color: "#fff" }}>
               <div style={{ fontSize: 14, opacity: 0.8 }}>Current Status</div>
               <div style={{ fontSize: 32, fontWeight: 900 }}>{tierPts} <span style={{ fontSize: 16 }}>PTS</span></div>
               <div style={{ marginTop: 12, fontWeight: 700 }}>{tier.icon} {tier.name}</div>
               <div style={{ height: 6, background: "rgba(255,255,255,0.2)", borderRadius: 3, marginTop: 8, overflow: "hidden" }}>
                  <div style={{ width: `${tierBarPct}%`, height: "100%", background: "#fff" }} />
               </div>
               {!isChamp && <div style={{ fontSize: 12, marginTop: 6 }}>{tierPtsLeft} pts to {nextTier.name}</div>}
            </div>
            <h2 style={{ marginBottom: 16 }}>Log Activity</h2>
            <div style={{ ...card, padding: 24 }}>
              <select value={form.rubricId} onChange={e => setForm({...form, rubricId: e.target.value})} style={{ ...inp, marginBottom: 16 }}>
                <option value="">Select activity...</option>
                {RUBRICS.map(r => <option key={r.id} value={r.id}>{r.icon} {r.activity} ({r.points} pts)</option>)}
              </select>
              <input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} style={{ ...inp, marginBottom: 16 }} />
              <textarea placeholder="Description/Evidence..." value={form.desc} onChange={e => setForm({...form, desc: e.target.value})} style={{ ...inp, height: 100, marginBottom: 20 }} />
              <button onClick={submitAct} disabled={!form.rubricId || !form.desc} style={{ width: "100%", padding: 14, borderRadius: 8, background: c.text, color: dark ? "#000" : "#fff", fontWeight: 700 }}>Submit Activity</button>
            </div>
          </div>
        )}

        {/* TAB: REWARDS (Consolidated) */}
        {tab === "rewards" && (
          <div className="up">
            <h2 style={{ textAlign: "center", marginBottom: 32 }}>Rewards Roadmap</h2>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 16, marginBottom: 60 }}>
              {TIERS.map(t => (
                <div key={t.name} style={{ ...card, padding: 20, textAlign: "center", borderTop: `4px solid ${t.color}` }}>
                  <div style={{ fontSize: 32, marginBottom: 8 }}>{t.icon}</div>
                  <div style={{ fontWeight: 800 }}>{t.name}</div>
                  <div style={{ fontSize: 12, color: c.sub }}>{t.min}+ pts</div>
                </div>
              ))}
            </div>

            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 24 }}>
              <h2>Prize Catalogue</h2>
              <div style={{ ...card, padding: "8px 16px", background: c.infoBg }}>
                <div style={{ fontSize: 11, color: c.muted }}>BALANCE</div>
                <div style={{ fontWeight: 900, fontSize: 18 }}>{myAvail} pts</div>
              </div>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))", gap: 20 }}>
              {catItems.map(p => (
                <div key={p.id} onClick={() => !p.tba && myAvail >= p.cost && setConfirm(p)} style={{ ...card, padding: 20, opacity: p.tba || myAvail < p.cost ? 0.5 : 1, cursor: p.tba ? "default" : "pointer" }}>
                  <div style={{ fontSize: 32, marginBottom: 12 }}>{p.icon}</div>
                  <div style={{ fontWeight: 800, fontSize: 16 }}>{p.name}</div>
                  <p style={{ fontSize: 13, color: c.sub, margin: "8px 0 16px" }}>{p.desc}</p>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <div style={{ fontWeight: 900 }}>{p.cost} pts</div>
                    {!p.tba && myAvail >= p.cost && <div style={{ color: c.goldText, fontWeight: 700 }}>Redeem →</div>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* TAB: LEADERBOARD */}
        {tab === "leaderboard" && (
          <div className="up">
             <div style={{ display: "flex", background: c.blank, padding: 4, borderRadius: 8, marginBottom: 32, maxWidth: 300, margin: "0 auto 32px" }}>
               <button onClick={()=>setLeaderboardTab("officers")} style={{ flex: 1, padding: 8, borderRadius: 6, border: "none", background: leaderboardTab === "officers" ? c.surface : "none", color: c.text, fontWeight: 700 }}>Officers</button>
               <button onClick={()=>setLeaderboardTab("branches")} style={{ flex: 1, padding: 8, borderRadius: 6, border: "none", background: leaderboardTab === "branches" ? c.surface : "none", color: c.text, fontWeight: 700 }}>Branches</button>
             </div>
             <div style={{ ...card, overflow: "hidden" }}>
                {(leaderboardTab === "officers" ? sorted : unitScores).map((item, i) => (
                  <div key={i} style={{ display: "flex", alignItems: "center", padding: "16px 20px", borderBottom: `1px solid ${c.border}` }}>
                    <span style={{ width: 40, fontWeight: 900, color: c.muted }}>#{i+1}</span>
                    <div style={{ flex: 1 }}>
                       <div style={{ fontWeight: 700 }}>{item.name || item.unit}</div>
                       <div style={{ fontSize: 12, color: c.muted }}>{item.unit || `${item.count} officers`}</div>
                    </div>
                    <div style={{ fontWeight: 900 }}>{item.total_points || item.avg} pts</div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {/* TAB: APPROVALS (Admin) */}
        {tab === "approvals" && isAdmin && (
          <div className="up">
            <h2 style={{ marginBottom: 24 }}>Pending Approvals</h2>
            {subs.filter(s => s.status === "pending").map(s => (
              <div key={s.id} style={{ ...card, padding: 20, marginBottom: 12, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ fontWeight: 800 }}>{s.officer_name} ({s.unit})</div>
                  <div style={{ fontSize: 14 }}>{s.activity} - {s.points} pts</div>
                  <div style={{ fontSize: 12, color: c.sub, marginTop: 4 }}>{s.description}</div>
                </div>
                <div style={{ display: "flex", gap: 8 }}>
                   <button onClick={() => approve(s)} style={{ padding: "8px 16px", borderRadius: 6, border: "none", background: "#10b981", color: "#fff", fontWeight: 700 }}>Approve</button>
                   <button onClick={async () => { await db.patch("submissions", `id=eq.${s.id}`, {status: "rejected"}); load(); }} style={{ padding: "8px 16px", borderRadius: 6, border: "none", background: "#ef4444", color: "#fff", fontWeight: 700 }}>Reject</button>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>
    </div>
  );
}

// ── SUBCOMPONENTS ──────────────────────────────────────────────────────────

const Manifesto = ({ c }) => (
  <div className="up">
    <h1 style={{ marginBottom: 24 }}>The GEAR Up Manifesto</h1>
    <div style={{ fontSize: 18, lineHeight: 1.8 }}>
      <p style={{ marginBottom: 20 }}><strong>Growth:</strong> Widen your horizons through every interaction.</p>
      <p style={{ marginBottom: 20 }}><strong>Expertise:</strong> Become an expert at the process of learning itself.</p>
      <p style={{ marginBottom: 20 }}><strong>Autonomy:</strong> You are the architect of your own potential.</p>
      <p><strong>Readiness:</strong> Be perpetually prepared for the future.</p>
    </div>
  </div>
);

const PointsGuide = ({ c, card }) => (
  <div className="up">
    <h1 style={{ marginBottom: 24 }}>Points Guide</h1>
    <div style={{ ...card, overflow: "hidden" }}>
      {RUBRICS.map(r => (
        <div key={r.id} style={{ padding: 16, borderBottom: `1px solid ${c.border}`, display: "flex", justifyContent: "space-between" }}>
          <span>{r.icon} {r.activity}</span>
          <span style={{ fontWeight: 800 }}>{r.points} pts</span>
        </div>
      ))}
    </div>
  </div>
);

const CSS = ({ c, dark }) => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap');
    body { margin: 0; background: ${c.bg}; }
    .up { animation: up 0.4s ease-out both; }
    @keyframes up { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
    .landing-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }
    @media (max-width: 850px) { .landing-grid { grid-template-columns: 1fr; } }
    .hamburger { background: none; border: none; font-size: 24px; color: ${c.text}; cursor: pointer; }
    .toast { position: fixed; top: 20px; right: 20px; padding: 12px 24px; border-radius: 8px; color: #fff; font-weight: 700; z-index: 1000; animation: toastIn 0.3s ease-out; }
    @keyframes toastIn { from { transform: translateX(100%); } to { transform: translateX(0); } }
    .modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.8); backdrop-filter: blur(4px); display: flex; align-items: center; justifyContent: center; z-index: 1000; padding: 20px; }
  `}</style>
);
